/**
 * Every active member of the org with their user record, unpaged — for
 * lookups that must see the whole membership (mention resolution) rather
 * than one screenful of it.
 */
export async function listActiveMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const rows = getDb()
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .orderBy(desc(members.createdAt), desc(members.id))
    .all();

  return rows.map((row) => ({ ...toMember(row.member), user: toUser(row.user) }));
}

/** The seat count every plan check compares against. */

