 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply that descends from it — directly or
 * through other replies — in order of posting. A deleted comment stays in
 * place as a placeholder (archived, text withheld) so the replies under it
 * keep their anchor.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(sql`${comments}.rowid`))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) =>
    withheldIfDeleted({
      ...toComment(row.comment),
      author: toUser(row.author),
    }),
  );

  const byId = new Map(decorated.map((comment) => [comment.id, comment]));

  /** Walks up the parent chain to the top-level comment a reply hangs off. */
  const rootOf = (comment: CommentWithAuthor): CommentWithAuthor | null => {
    let current = comment;
    const visited = new Set<CommentId>();
    while (current.parentId !== null) {
      if (visited.has(current.id)) return null;
      visited.add(current.id);
      const parent = byId.get(current.parentId);
      if (parent === undefined) return null;
      current = parent;
    }
    return current;
  };

  const repliesBy = new Map<CommentId, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const root = rootOf(comment);
    if (root === null) continue;
    const bucket = repliesBy.get(root.id) ?? [];
    bucket.push(comment);
    repliesBy.set(root.id, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

/** A deleted comment keeps its place in the thread but not its content. */
function withheldIfDeleted(comment: CommentWithAuthor): CommentWithAuthor {
  if (comment.archivedAt === null) return comment;
  return { ...comment, body: "", mentionedUserIds: [] };
}

