 * Who hears about a new comment besides the people it mentions: the issue's
 * author, its current assignee and, for a reply, the author of the comment
 * being answered.
 */
async function commentWatchers(
  orgId: OrgId,
  issueId: IssueId,
  commentId: CommentId,
): Promise<readonly UserId[]> {
  const watchers: UserId[] = [];

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue) {
    watchers.push(issue.authorId);
    if (issue.assigneeId) watchers.push(issue.assigneeId);
  }

  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment?.parentId) {
    const parent = await commentRepo.findCommentById(orgId, comment.parentId);
    if (parent) watchers.push(parent.authorId);
  }

  return watchers;
}

