import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { registerEventHandlers } from "@/server/services/event-registry";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { UserId } from "@/types/common";

let cleanup: () => void;
let t: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  t = await createTenant("scen", "growth");
  other = await createTenant("scen-other", "growth");
});
afterAll(() => cleanup());

async function alerts(userId: UserId) {
  const page = await listNotifications(t.actors.owner, {
    orgId: t.org.id,
    recipientId: userId,
    unreadOnly: false,
    kind: [],
    limit: 100,
    cursor: null,
  } as never);
  return page.items;
}

describe("scenarios", () => {
  it("mentions oldest members in big orgs, viewers, shared handles", async () => {
    // owner is the oldest member; add 130 more
    for (let i = 0; i < 130; i++) {
      const u = await userRepo.insertUser({ email: `filler${i}@scen.test`, name: `f${i}`, passwordHash: "x" });
      await memberRepo.insertMember(t.org.id, u.id, "member", null);
    }
    const dupe = await userRepo.insertUser({ email: "Viewer@elsewhere.test", name: "dup", passwordHash: "x" });
    await memberRepo.insertMember(t.org.id, dupe.id, "member", null);
    const short = await userRepo.insertUser({ email: "q@x.test", name: "q", passwordHash: "x" });
    await memberRepo.insertMember(t.org.id, short.id, "member", null);

    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    const before = (await alerts(t.userIds.owner)).length;
    const c = await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue.id, body: "@OWNER and @viewer and @member and @q `@admin`", parentId: null, mentionedUserIds: [other.userIds.admin],
    });
    expect([...c.mentionedUserIds].sort()).toEqual([t.userIds.owner, t.userIds.viewer, dupe.id, short.id].sort());
    expect((await alerts(t.userIds.owner)).length).toBe(before + 1);
    expect((await alerts(t.userIds.viewer)).map((n) => n.kind)).toContain("comment_mention");
    expect((await alerts(t.userIds.member)).length).toBe(0);
  });

  it("one alert for a mentioned assignee; reply author notified; threads", async () => {
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.admin }));
    const adminBefore = (await alerts(t.userIds.admin)).length;
    const top = await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "hey @admin", parentId: null, mentionedUserIds: [] });
    const adminAfter = await alerts(t.userIds.admin);
    expect(adminAfter.length).toBe(adminBefore + 1);
    const viewerBefore = (await alerts(t.userIds.viewer)).length;
    // viewer can't post, so make admin reply, then owner replies to that reply; admin should be told
    const r1 = await commentService.createComment(t.actors.viewer === undefined ? t.actors.admin : t.actors.admin, { orgId: t.org.id, issueId: issue.id, body: "reply1", parentId: top.id, mentionedUserIds: [] });
    const ownerAlerts = (await alerts(t.userIds.owner)).length;
    const r2 = await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "reply2", parentId: r1.id, mentionedUserIds: [] });
    expect((await alerts(t.userIds.owner)).length).toBe(ownerAlerts); // owner not issue author, not parent author
    const r3 = await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "reply3", parentId: r2.id, mentionedUserIds: [] });
    expect((await alerts(t.userIds.viewer)).length).toBe(viewerBefore);
    const top2 = await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "second top", parentId: null, mentionedUserIds: [] });

    await commentService.deleteComment(t.actors.admin, { orgId: t.org.id, commentId: r1.id });
    const thread = await commentService.getThread(t.actors.member, t.org.id, issue.id);
    expect(thread.map((n) => n.comment.id)).toEqual([top.id, top2.id]);
    expect(thread[0]!.replies.map((r) => r.id)).toEqual([r1.id, r2.id, r3.id]);
    expect(thread[0]!.replies[0]!.body).toBe("");
    expect(thread[0]!.replies[0]!.archivedAt).not.toBeNull();

